// Banque de questions.
// d = domaine, q = énoncé, a = réponses, c = index de la bonne réponse
// (ou tableau d'index pour une question à réponses multiples), e = explication.
// L'ordre des réponses est mélangé à l'affichage.
const QUESTIONS = [
  // ── Domaine 1 : Concepts du cloud ─────────────────────────────────────────
  { d: 1, q: "Quel est le principal avantage du modèle de paiement à l’usage d’AWS ?", a: ["Payer un montant fixe chaque année", "Payer uniquement les ressources consommées", "Obtenir gratuitement le support Enterprise", "Ne plus avoir aucune configuration à faire"], c: 1, e: "AWS facture les ressources réellement consommées : les coûts suivent l’activité et on évite un investissement initial important." },
  { d: 1, q: "Pourquoi déployer une application sur plusieurs Availability Zones ?", a: ["Supprimer toute facturation", "Améliorer la tolérance aux pannes et la disponibilité", "Remplacer les sauvegardes", "Ne plus avoir besoin d’IAM"], c: 1, e: "Les Availability Zones sont isolées les unes des autres. Répartir les composants entre plusieurs AZ permet de résister à la panne d’un datacenter." },
  { d: 1, q: "Quelle est la meilleure description d’une Région AWS ?", a: ["Un datacenter unique", "Une zone géographique contenant plusieurs Availability Zones isolées", "Un compte partagé entre clients", "Un réseau privé virtuel"], c: 1, e: "Une Région est une zone géographique distincte composée de plusieurs Availability Zones isolées et reliées par un réseau à faible latence." },
  { d: 1, q: "Une entreprise ne veut plus acheter de serveurs à l’avance et préfère payer selon sa consommation. Quel avantage du cloud cela illustre-t-il ?", a: ["Se déployer mondialement en quelques minutes", "Remplacer les dépenses d’investissement par des dépenses variables", "Bénéficier d’économies d’échelle massives", "Augmenter la vitesse et l’agilité"], c: 1, e: "Passer du CapEx (achat de matériel) à l’OpEx (dépenses variables) est l’un des six avantages du cloud." },
  { d: 1, q: "Quelle caractéristique du cloud permet d’ajuster automatiquement les ressources à la hausse ou à la baisse selon la demande ?", a: ["La durabilité", "L’élasticité", "La conformité", "La latence"], c: 1, e: "L’élasticité est la capacité à acquérir des ressources quand on en a besoin et à les libérer quand elles ne sont plus utiles." },
  { d: 1, q: "Un site de vente subit de forts pics de trafic lors des soldes. Quel avantage du cloud lui évite de surdimensionner son infrastructure ?", a: ["Arrêter de deviner la capacité", "Payer des licences à l’avance", "Utiliser un seul datacenter", "Réduire le nombre d’Availability Zones"], c: 0, e: "Dans le cloud, la capacité s’adapte à la demande réelle : inutile de prévoir et d’acheter du matériel pour le pic maximal." },
  { d: 1, q: "Pourquoi AWS peut-il proposer des prix plus bas qu’un datacenter d’entreprise ?", a: ["Grâce aux économies d’échelle", "Parce qu’AWS ne facture pas le stockage", "Parce que le client gère le matériel", "Parce que les Régions sont gratuites"], c: 0, e: "L’agrégation de l’utilisation de centaines de milliers de clients permet à AWS de réaliser des économies d’échelle et de baisser ses prix." },
  { d: 1, q: "Une startup veut servir des clients en Asie et en Europe avec une faible latence sans construire de datacenters. Quel avantage du cloud cela illustre-t-il ?", a: ["Remplacer le CapEx par l’OpEx", "Se déployer mondialement en quelques minutes", "Arrêter de deviner la capacité", "Économies d’échelle"], c: 1, e: "L’infrastructure mondiale d’AWS permet de déployer une application dans plusieurs Régions en quelques minutes." },
  { d: 1, q: "Quel service est un exemple d’Infrastructure as a Service (IaaS) ?", a: ["Amazon EC2", "AWS Elastic Beanstalk", "Amazon WorkMail", "Amazon QuickSight"], c: 0, e: "Amazon EC2 fournit des serveurs virtuels : le client gère l’OS, les middlewares et les applications, ce qui correspond à l’IaaS." },
  { d: 1, q: "Quel service AWS correspond le mieux au modèle Platform as a Service (PaaS) ?", a: ["Amazon EC2", "AWS Elastic Beanstalk", "Amazon EBS", "AWS Direct Connect"], c: 1, e: "Avec Elastic Beanstalk, on déploie son code et AWS gère la capacité, l’équilibrage de charge, la mise à l’échelle et la supervision." },
  { d: 1, q: "Quelle affirmation décrit le Software as a Service (SaaS) ?", a: ["Le client gère le système d’exploitation", "Le client déploie son code sur une plateforme managée", "Le fournisseur livre une application complète qu’il gère entièrement", "Le client loue du matériel physique"], c: 2, e: "En SaaS, l’utilisateur consomme une application finie ; le fournisseur gère l’infrastructure, la plateforme et le logiciel." },
  { d: 1, q: "Une entreprise garde des applications dans son datacenter et les connecte à des ressources AWS. Quel modèle de déploiement utilise-t-elle ?", a: ["Tout dans le cloud", "Hybride", "Sur site uniquement", "SaaS"], c: 1, e: "Un déploiement hybride relie l’infrastructure sur site aux ressources cloud." },
  { d: 1, q: "Quels facteurs doivent guider le choix d’une Région AWS ? (Choisissez 2 réponses)", a: ["Les exigences de conformité et de localisation des données", "La proximité avec les utilisateurs", "Le nombre d’utilisateurs IAM du compte", "La couleur du thème de la console", "La taille du compte root"], c: [0, 1], e: "On choisit une Région selon la conformité, la proximité des utilisateurs (latence), la disponibilité des services et la tarification." },
  { d: 1, q: "Quels composants de l’infrastructure mondiale AWS sont utilisés par Amazon CloudFront pour mettre du contenu en cache près des utilisateurs ?", a: ["Les Availability Zones", "Les emplacements périphériques (edge locations)", "Les VPC", "Les Outposts"], c: 1, e: "CloudFront utilise un réseau mondial d’emplacements périphériques pour servir le contenu avec une faible latence." },
  { d: 1, q: "Quelle solution permet d’exécuter une infrastructure et des services AWS dans le datacenter du client ?", a: ["AWS Local Zones", "AWS Wavelength", "AWS Outposts", "Amazon CloudFront"], c: 2, e: "AWS Outposts installe du matériel géré par AWS sur site pour une expérience hybride cohérente." },
  { d: 1, q: "Quelle offre place des ressources AWS à proximité de grandes zones urbaines pour une latence de l’ordre de la milliseconde ?", a: ["AWS Local Zones", "AWS Snowball", "Amazon Route 53", "AWS Organizations"], c: 0, e: "Les Local Zones rapprochent le calcul, le stockage et les bases de données des utilisateurs situés dans de grandes villes." },
  { d: 1, q: "Quel service intègre l’infrastructure AWS aux réseaux 5G des opérateurs télécoms ?", a: ["AWS Outposts", "AWS Wavelength", "AWS Direct Connect", "AWS Global Accelerator"], c: 1, e: "AWS Wavelength permet des applications à ultra faible latence pour les appareils mobiles connectés en 5G." },
  { d: 1, q: "Quel pilier du Well-Architected Framework porte sur la capacité d’une charge de travail à se remettre des pannes ?", a: ["Efficacité des performances", "Fiabilité", "Excellence opérationnelle", "Optimisation des coûts"], c: 1, e: "Le pilier Fiabilité couvre la reprise après panne, la gestion des changements et l’adaptation à la demande." },
  { d: 1, q: "Quel pilier du Well-Architected Framework vise à réduire l’impact environnemental des charges de travail ?", a: ["Durabilité", "Sécurité", "Fiabilité", "Excellence opérationnelle"], c: 0, e: "Le pilier Durabilité, ajouté en 2021, cherche à minimiser la consommation d’énergie et de ressources." },
  { d: 1, q: "Choisir le bon type et la bonne taille de ressources pour répondre efficacement aux besoins relève de quel pilier ?", a: ["Efficacité des performances", "Sécurité", "Durabilité", "Fiabilité"], c: 0, e: "L’efficacité des performances consiste à utiliser les ressources informatiques efficacement et à maintenir cette efficacité quand la demande évolue." },
  { d: 1, q: "Automatiser les déploiements et effectuer de petits changements fréquents et réversibles relève de quel pilier ?", a: ["Optimisation des coûts", "Excellence opérationnelle", "Durabilité", "Sécurité"], c: 1, e: "L’excellence opérationnelle concerne l’exécution et la supervision des systèmes et l’amélioration continue des processus." },
  { d: 1, q: "Quels éléments font partie des piliers du AWS Well-Architected Framework ? (Choisissez 2 réponses)", a: ["Sécurité", "Optimisation des coûts", "Élasticité", "Scalabilité", "Migration"], c: [0, 1], e: "Les six piliers sont : excellence opérationnelle, sécurité, fiabilité, efficacité des performances, optimisation des coûts et durabilité." },
  { d: 1, q: "Quel outil permet d’évaluer une charge de travail par rapport aux bonnes pratiques d’architecture AWS ?", a: ["AWS Well-Architected Tool", "AWS Artifact", "Amazon Inspector", "AWS Pricing Calculator"], c: 0, e: "Le AWS Well-Architected Tool pose des questions sur chaque pilier et propose un plan d’amélioration." },
  { d: 1, q: "Quelle perspective du AWS Cloud Adoption Framework (CAF) couvre la culture, la formation et la gestion du changement ?", a: ["Plateforme", "Personnes", "Opérations", "Sécurité"], c: 1, e: "La perspective Personnes aide à faire évoluer la culture, les compétences et l’organisation vers le cloud." },
  { d: 1, q: "Quelles perspectives du AWS CAF sont centrées sur les capacités techniques ? (Choisissez 2 réponses)", a: ["Plateforme", "Opérations", "Business", "Gouvernance", "Personnes"], c: [0, 1], e: "Les perspectives techniques sont Plateforme, Sécurité et Opérations ; Business, Personnes et Gouvernance sont les perspectives métier." },
  { d: 1, q: "Déplacer une application sur AWS sans la modifier correspond à quelle stratégie de migration ?", a: ["Refactor", "Rehost (lift and shift)", "Repurchase", "Retire"], c: 1, e: "Rehost consiste à migrer tel quel, souvent pour aller vite et optimiser ensuite." },
  { d: 1, q: "Une entreprise migre son application et déplace sa base MySQL vers Amazon RDS sans modifier le code. Quelle stratégie utilise-t-elle ?", a: ["Rehost", "Replatform", "Refactor", "Retain"], c: 1, e: "Replatform (lift, tinker and shift) apporte quelques optimisations cloud sans changer l’architecture de base." },
  { d: 1, q: "Réécrire une application monolithique en microservices serverless correspond à quelle stratégie de migration ?", a: ["Refactor / Re-architect", "Relocate", "Rehost", "Repurchase"], c: 0, e: "Refactor consiste à repenser l’architecture pour exploiter les fonctionnalités cloud natives." },
  { d: 1, q: "Lors de l’analyse d’un portefeuille, une application n’est plus utilisée. Quelle stratégie de migration appliquer ?", a: ["Retain", "Retire", "Rehost", "Replatform"], c: 1, e: "Retire consiste à décommissionner les applications inutiles, ce qui réduit les coûts et la surface d’attaque." },
  { d: 1, q: "Une entreprise doit transférer 80 To de données vers AWS mais sa connexion Internet est lente. Quelle solution est la plus adaptée ?", a: ["AWS Snowball", "Amazon CloudFront", "AWS Site-to-Site VPN", "Amazon SQS"], c: 0, e: "Les appareils de la famille AWS Snow permettent de transférer physiquement de grandes quantités de données quand le réseau est insuffisant." },
  { d: 1, q: "Quel service permet de migrer une base de données vers AWS avec un temps d’arrêt minimal ?", a: ["AWS Database Migration Service (DMS)", "AWS Backup", "Amazon Athena", "AWS Glue"], c: 0, e: "AWS DMS réplique les données pendant la migration : la base source reste opérationnelle." },
  { d: 1, q: "Quel service collecte des informations sur les serveurs sur site pour planifier une migration ?", a: ["AWS Application Discovery Service", "AWS Config", "Amazon Inspector", "AWS Trusted Advisor"], c: 0, e: "Application Discovery Service inventorie les serveurs, leur utilisation et leurs dépendances." },
  { d: 1, q: "Quel principe de conception consiste à utiliser Amazon SQS entre deux composants d’une application ?", a: ["Le couplage fort", "Le découplage (loose coupling)", "La mise à l’échelle verticale", "Le point unique de défaillance"], c: 1, e: "Une file d’attente découple les composants : une panne ou un ralentissement de l’un n’affecte pas directement l’autre." },
  { d: 1, q: "Ajouter des instances EC2 supplémentaires pour absorber une charge plus élevée est un exemple de :", a: ["Mise à l’échelle verticale", "Mise à l’échelle horizontale", "Haute durabilité", "Migration rehost"], c: 1, e: "La mise à l’échelle horizontale ajoute des ressources ; la verticale augmente la taille d’une ressource existante." },
  { d: 1, q: "Quel coût une entreprise élimine-t-elle en passant d’un datacenter sur site au cloud AWS ?", a: ["Le coût de développement de ses applications", "Le renouvellement du matériel serveur et le refroidissement du datacenter", "La formation de ses équipes", "Les licences de ses logiciels métier dans tous les cas"], c: 1, e: "AWS prend en charge le matériel, l’électricité, le refroidissement et les locaux : ces coûts disparaissent du TCO du client." },
  { d: 1, q: "Quel est un avantage des architectures serverless ?", a: ["Accès root aux serveurs physiques", "Aucun serveur à provisionner ni à gérer et paiement à l’exécution", "Tarif fixe mensuel quelle que soit l’utilisation", "Contrôle total de l’hyperviseur"], c: 1, e: "En serverless, AWS gère l’infrastructure, la mise à l’échelle et la disponibilité ; on paie uniquement l’usage." },
  { d: 1, q: "Qu’est-ce qu’une Availability Zone ?", a: ["Un emplacement périphérique de CloudFront", "Un ou plusieurs datacenters distincts avec alimentation et réseau redondants", "Un groupe de Régions", "Un sous-réseau d’un VPC"], c: 1, e: "Une AZ est composée d’un ou plusieurs datacenters isolés, situés dans une Région." },

  // ── Domaine 2 : Sécurité et conformité ────────────────────────────────────
  { d: 2, q: "Quelle tâche relève toujours du client dans le modèle de responsabilité partagée ?", a: ["La sécurité physique des datacenters", "La maintenance du matériel AWS", "La gestion des identités et des accès", "La protection du réseau mondial AWS"], c: 2, e: "AWS sécurise l’infrastructure du cloud. Le client reste responsable de la sécurité dans le cloud, notamment des utilisateurs et des permissions." },
  { d: 2, q: "Quelle pratique est recommandée pour le compte root AWS ?", a: ["L’utiliser pour les tâches quotidiennes", "Partager ses identifiants avec l’équipe", "Activer MFA et limiter son usage", "Créer des clés d’accès pour les scripts"], c: 2, e: "Le compte root a des privilèges illimités. Il faut le protéger avec MFA et le réserver aux rares tâches qui l’exigent." },
  { d: 2, q: "Selon le modèle de responsabilité partagée, de quoi AWS est-il responsable ?", a: ["Du chiffrement des données client", "De la sécurité physique des datacenters", "Des règles des security groups", "Des permissions IAM"], c: 1, e: "AWS est responsable de la sécurité « du » cloud : bâtiments, matériel, réseau et hyperviseur." },
  { d: 2, q: "Qui applique les correctifs du système d’exploitation invité d’une instance Amazon EC2 ?", a: ["AWS", "Le client", "Le fournisseur de l’AMI", "AWS Support"], c: 1, e: "EC2 est un service IaaS : le client gère l’OS invité, ses correctifs et les logiciels installés." },
  { d: 2, q: "Qui applique les correctifs du moteur de base de données sur Amazon RDS ?", a: ["Le client, via SSH", "AWS", "Le partenaire AWS", "Personne, ils ne sont pas nécessaires"], c: 1, e: "RDS est un service managé : AWS gère l’OS et les correctifs du moteur, le client choisit la fenêtre de maintenance." },
  { d: 2, q: "Lequel de ces contrôles est partagé entre AWS et le client ?", a: ["La sécurité physique", "La gestion des correctifs", "La destruction des disques", "Le contrôle d’accès aux bâtiments"], c: 1, e: "Les contrôles partagés sont la gestion des correctifs, la gestion de la configuration, et la sensibilisation et la formation." },
  { d: 2, q: "Quelles tâches relèvent de la responsabilité du client ? (Choisissez 2 réponses)", a: ["Configurer les security groups", "Chiffrer les données sensibles", "Maintenir l’hyperviseur", "Sécuriser physiquement les serveurs", "Remplacer les disques défectueux"], c: [0, 1], e: "Le client configure ses pare-feu virtuels et protège ses données. Le matériel et la virtualisation relèvent d’AWS." },
  { d: 2, q: "Que signifie le principe du moindre privilège ?", a: ["Donner les droits administrateur à tous pour éviter les blocages", "Accorder uniquement les permissions nécessaires pour accomplir une tâche", "Supprimer tous les utilisateurs IAM", "Utiliser uniquement le compte root"], c: 1, e: "Le moindre privilège limite l’impact d’une erreur ou d’un identifiant compromis." },
  { d: 2, q: "Une application sur EC2 doit lire des objets dans Amazon S3. Quelle est la méthode la plus sécurisée ?", a: ["Stocker des clés d’accès dans le code", "Attacher un rôle IAM à l’instance", "Utiliser les identifiants du compte root", "Rendre le bucket public"], c: 1, e: "Un rôle IAM fournit des identifiants temporaires renouvelés automatiquement, sans secret stocké sur l’instance." },
  { d: 2, q: "Comment attribuer facilement les mêmes permissions à 20 développeurs ?", a: ["Créer un groupe IAM et y attacher une politique", "Partager un seul utilisateur IAM", "Utiliser le compte root", "Créer 20 comptes AWS"], c: 0, e: "Les groupes IAM permettent de gérer les permissions d’un ensemble d’utilisateurs en un seul endroit." },
  { d: 2, q: "Sous quel format sont écrites les politiques IAM ?", a: ["XML", "YAML", "JSON", "CSV"], c: 2, e: "Une politique IAM est un document JSON avec des instructions Effect, Action, Resource et éventuellement Condition." },
  { d: 2, q: "Quelle tâche nécessite de se connecter avec le compte root ?", a: ["Créer un bucket S3", "Fermer le compte AWS", "Lancer une instance EC2", "Créer un utilisateur IAM"], c: 1, e: "Certaines tâches, comme fermer le compte ou modifier certains paramètres du compte, sont réservées au root." },
  { d: 2, q: "Quel service offre l’authentification unique (SSO) à plusieurs comptes AWS et applications ?", a: ["AWS IAM Identity Center", "Amazon Cognito", "AWS Secrets Manager", "AWS KMS"], c: 0, e: "IAM Identity Center centralise l’accès des collaborateurs à plusieurs comptes AWS et applications métier." },
  { d: 2, q: "Qu’apporte l’authentification multifacteur (MFA) ?", a: ["Elle chiffre les données S3", "Elle ajoute un second facteur de vérification en plus du mot de passe", "Elle supprime le besoin de mot de passe", "Elle accélère la connexion"], c: 1, e: "Avec MFA, un mot de passe volé ne suffit pas : il faut aussi un code ou une clé de sécurité." },
  { d: 2, q: "À quoi servent les clés d’accès IAM (access key ID et secret) ?", a: ["Se connecter à la console web", "Accéder à AWS par programme via la CLI ou les SDK", "Chiffrer des volumes EBS", "Ouvrir la porte d’un datacenter"], c: 1, e: "Les clés d’accès servent à l’accès programmatique. Elles doivent être protégées et régulièrement renouvelées." },
  { d: 2, q: "Quel service gère l’inscription et la connexion des utilisateurs finaux d’une application mobile ?", a: ["AWS IAM", "Amazon Cognito", "AWS Organizations", "AWS Directory Service"], c: 1, e: "Amazon Cognito fournit l’authentification, l’autorisation et la gestion des utilisateurs pour les applications web et mobiles." },
  { d: 2, q: "Quel service protège gratuitement et automatiquement tous les clients AWS contre les attaques DDoS courantes ?", a: ["AWS Shield Standard", "AWS Shield Advanced", "Amazon GuardDuty", "AWS WAF"], c: 0, e: "Shield Standard est inclus sans frais et protège contre les attaques DDoS les plus fréquentes aux couches 3 et 4." },
  { d: 2, q: "Quel service donne accès 24/7 à une équipe de réponse DDoS et inclut une protection contre les hausses de coûts liées à une attaque ?", a: ["AWS Shield Advanced", "AWS Shield Standard", "Amazon Inspector", "AWS Firewall Manager"], c: 0, e: "Shield Advanced offre une protection renforcée, l’équipe Shield Response Team et une protection des coûts." },
  { d: 2, q: "Quel service bloque les injections SQL et le cross-site scripting au niveau applicatif ?", a: ["AWS WAF", "Network ACL", "AWS Shield Standard", "Amazon Macie"], c: 0, e: "AWS WAF est un pare-feu d’application web qui filtre les requêtes HTTP(S) selon des règles." },
  { d: 2, q: "Quel service analyse les journaux CloudTrail, les journaux de flux VPC et DNS pour détecter des activités malveillantes ?", a: ["Amazon GuardDuty", "AWS Config", "Amazon Inspector", "AWS Artifact"], c: 0, e: "GuardDuty est un service de détection des menaces qui utilise le machine learning et le renseignement sur les menaces." },
  { d: 2, q: "Quel service analyse automatiquement les instances EC2 et les images de conteneurs à la recherche de vulnérabilités logicielles ?", a: ["Amazon Inspector", "Amazon Macie", "AWS Shield", "Amazon Detective"], c: 0, e: "Amazon Inspector recherche en continu les vulnérabilités logicielles et les expositions réseau involontaires." },
  { d: 2, q: "Quel service découvre les données personnelles sensibles (PII) stockées dans Amazon S3 ?", a: ["Amazon Macie", "Amazon GuardDuty", "AWS KMS", "AWS CloudTrail"], c: 0, e: "Macie utilise le machine learning pour identifier et protéger les données sensibles dans S3." },
  { d: 2, q: "Quel service permet de créer et de contrôler les clés utilisées pour chiffrer les données ?", a: ["AWS Key Management Service (KMS)", "AWS Certificate Manager", "Amazon Cognito", "AWS Secrets Manager"], c: 0, e: "AWS KMS crée et gère des clés de chiffrement intégrées à de nombreux services AWS." },
  { d: 2, q: "Une réglementation impose que les clés de chiffrement soient stockées dans un module matériel dédié au client. Quel service utiliser ?", a: ["AWS CloudHSM", "AWS KMS avec clés gérées par AWS", "Amazon Macie", "AWS Artifact"], c: 0, e: "CloudHSM fournit des modules matériels de sécurité mono-locataires sous le contrôle exclusif du client." },
  { d: 2, q: "Quel service stocke les identifiants d’une base de données et les fait tourner automatiquement ?", a: ["AWS Secrets Manager", "AWS KMS", "Amazon S3", "AWS IAM Identity Center"], c: 0, e: "Secrets Manager stocke les secrets de manière chiffrée et peut les renouveler automatiquement." },
  { d: 2, q: "Quel service fournit et renouvelle des certificats SSL/TLS pour sécuriser un site web ?", a: ["AWS Certificate Manager (ACM)", "AWS CloudHSM", "AWS WAF", "Amazon Route 53"], c: 0, e: "ACM provisionne, gère et renouvelle les certificats SSL/TLS utilisés avec ELB, CloudFront ou API Gateway." },
  { d: 2, q: "Quel service regroupe dans un tableau de bord unique les alertes de GuardDuty, Inspector et Macie ainsi que des contrôles de conformité ?", a: ["AWS Security Hub", "Amazon CloudWatch", "AWS Trusted Advisor", "AWS Artifact"], c: 0, e: "Security Hub centralise les résultats de sécurité et évalue la posture par rapport à des normes." },
  { d: 2, q: "Quel service aide à investiguer la cause racine d’un incident de sécurité ?", a: ["Amazon Detective", "Amazon Inspector", "AWS Shield", "AWS Budgets"], c: 0, e: "Detective analyse et visualise les données de sécurité pour faciliter les enquêtes." },
  { d: 2, q: "Un auditeur veut savoir quel utilisateur a supprimé un bucket S3 hier. Quel service consulter ?", a: ["AWS CloudTrail", "Amazon CloudWatch Metrics", "AWS Trusted Advisor", "Amazon Inspector"], c: 0, e: "CloudTrail enregistre les appels d’API : identité, heure, adresse IP source et paramètres." },
  { d: 2, q: "Quel service suit l’historique des modifications de configuration des ressources et évalue leur conformité à des règles ?", a: ["AWS Config", "AWS CloudTrail", "Amazon GuardDuty", "AWS Systems Manager"], c: 0, e: "AWS Config enregistre l’état des ressources dans le temps et signale celles qui ne respectent pas les règles définies." },
  { d: 2, q: "Où télécharger les rapports de conformité d’AWS, comme les rapports SOC ou l’attestation PCI DSS ?", a: ["AWS Artifact", "AWS Audit Manager", "AWS Config", "AWS Security Hub"], c: 0, e: "AWS Artifact est le portail en libre-service des rapports de conformité et des accords AWS." },
  { d: 2, q: "Quelle fonctionnalité d’AWS Organizations limite les actions autorisées dans les comptes membres, même pour leurs administrateurs ?", a: ["Les Service Control Policies (SCP)", "Les groupes IAM", "Les security groups", "Les balises de coûts"], c: 0, e: "Les SCP définissent les permissions maximales disponibles dans les comptes d’une organisation." },
  { d: 2, q: "Quel service met en place rapidement un environnement multi-comptes sécurisé avec des garde-fous ?", a: ["AWS Control Tower", "AWS CloudFormation", "Amazon VPC", "AWS Backup"], c: 0, e: "Control Tower automatise la création d’une zone d’atterrissage (landing zone) basée sur les bonnes pratiques." },
  { d: 2, q: "Quel service automatise la collecte de preuves pour préparer un audit ?", a: ["AWS Audit Manager", "AWS Artifact", "Amazon Macie", "AWS Cost Explorer"], c: 0, e: "Audit Manager évalue en continu l’utilisation d’AWS et collecte des preuves selon des référentiels." },
  { d: 2, q: "Quelles mesures protègent les données d’une application ? (Choisissez 2 réponses)", a: ["Chiffrer les données au repos avec AWS KMS", "Chiffrer les données en transit avec TLS", "Rendre les buckets S3 publics", "Désactiver CloudTrail", "Partager les clés d’accès par e-mail"], c: [0, 1], e: "On protège les données au repos (KMS, chiffrement S3, EBS) et en transit (HTTPS/TLS)." },
  { d: 2, q: "Quelle affirmation décrit un security group ?", a: ["Pare-feu sans état au niveau du sous-réseau", "Pare-feu avec état au niveau de l’instance", "Service de détection des menaces", "Liste de refus au niveau de la Région"], c: 1, e: "Un security group est avec état : le trafic de retour d’une connexion autorisée est automatiquement permis. Il ne contient que des règles d’autorisation." },
  { d: 2, q: "Quelle affirmation décrit une network ACL ?", a: ["Pare-feu sans état au niveau du sous-réseau, avec règles d’autorisation et de refus", "Pare-feu avec état au niveau de l’instance", "Service de chiffrement", "Politique IAM attachée à un utilisateur"], c: 0, e: "Les network ACL sont sans état : le trafic entrant et sortant doit être autorisé explicitement." },
  { d: 2, q: "Quel service vérifie par exemple si MFA est activé sur le compte root ou si des ports sont ouverts sans restriction ?", a: ["AWS Trusted Advisor", "AWS Artifact", "Amazon Polly", "AWS Pricing Calculator"], c: 0, e: "Trusted Advisor inclut des contrôles de sécurité, dont certains sont disponibles avec tous les plans de support." },
  { d: 2, q: "Qui contacter pour signaler qu’une ressource AWS est utilisée pour envoyer du spam ou mener une attaque ?", a: ["L’équipe AWS Trust & Safety", "AWS Marketplace", "AWS Professional Services", "L’équipe de facturation"], c: 0, e: "L’équipe AWS Trust & Safety traite les signalements d’utilisation abusive des ressources AWS." },
  { d: 2, q: "Une entreprise héberge des données de santé sur une infrastructure AWS conforme. Qui est responsable de la conformité de son application ?", a: ["AWS uniquement", "Le client", "L’auditeur externe uniquement", "Personne, l’infrastructure est certifiée"], c: 1, e: "AWS fournit une infrastructure conforme, mais le client doit rendre sa propre application et ses processus conformes." },
  { d: 2, q: "Quel outil identifie les ressources (buckets S3, rôles IAM…) partagées avec une entité externe au compte ?", a: ["IAM Access Analyzer", "AWS Budgets", "Amazon CloudFront", "AWS Health Dashboard"], c: 0, e: "IAM Access Analyzer détecte les accès externes involontaires et aide à valider les politiques." },
  { d: 2, q: "Quel service gère de manière centralisée les règles AWS WAF et Shield Advanced sur plusieurs comptes ?", a: ["AWS Firewall Manager", "AWS Config", "Amazon VPC", "AWS Control Tower"], c: 0, e: "Firewall Manager applique les règles de protection de manière cohérente dans toute une organisation." },

  // ── Domaine 3 : Technologie et services cloud ─────────────────────────────
  { d: 3, q: "Quel service fournit un stockage objet durable et hautement disponible ?", a: ["Amazon EC2", "Amazon RDS", "Amazon S3", "Amazon VPC"], c: 2, e: "Amazon S3 est le service de stockage objet d’AWS, avec plusieurs classes selon les besoins d’accès et de coût." },
  { d: 3, q: "Quel service exécute du code sans gérer de serveurs ?", a: ["Amazon ECS sur EC2", "AWS Lambda", "Amazon Lightsail", "AWS Direct Connect"], c: 1, e: "AWS Lambda exécute du code en réponse à des événements. AWS gère les serveurs et la mise à l’échelle." },
  { d: 3, q: "Quel service est une base de données relationnelle managée ?", a: ["Amazon DynamoDB", "Amazon Neptune", "Amazon RDS", "Amazon ElastiCache"], c: 2, e: "Amazon RDS simplifie la mise en place et l’exploitation de bases comme MySQL, PostgreSQL ou SQL Server." },
  { d: 3, q: "Une application utilise une grande base de données en mémoire. Quelle famille d’instances EC2 choisir ?", a: ["Optimisées pour le calcul", "Optimisées pour la mémoire", "Optimisées pour le stockage", "Usage général"], c: 1, e: "Les instances optimisées pour la mémoire offrent beaucoup de RAM pour traiter de grands jeux de données en mémoire." },
  { d: 3, q: "Quelle famille d’instances EC2 convient au calcul haute performance, au traitement par lots et aux serveurs de jeux ?", a: ["Optimisées pour le calcul", "Optimisées pour la mémoire", "Optimisées pour le stockage", "Calcul accéléré"], c: 0, e: "Les instances optimisées pour le calcul disposent de processeurs hautes performances." },
  { d: 3, q: "Quel service ajoute ou retire automatiquement des instances EC2 selon la charge ?", a: ["Amazon EC2 Auto Scaling", "Elastic Load Balancing", "AWS Batch", "Amazon CloudFront"], c: 0, e: "EC2 Auto Scaling maintient la disponibilité et ajuste le nombre d’instances à la demande." },
  { d: 3, q: "Quel service répartit le trafic entrant entre plusieurs instances EC2 dans plusieurs Availability Zones ?", a: ["Elastic Load Balancing", "Amazon Route 53 Resolver", "AWS Direct Connect", "Amazon SQS"], c: 0, e: "Elastic Load Balancing distribue le trafic entre des cibles saines et améliore la tolérance aux pannes." },
  { d: 3, q: "Un développeur veut déployer une application web Java en téléversant son code, sans configurer l’infrastructure. Quel service utiliser ?", a: ["AWS Elastic Beanstalk", "Amazon EC2", "AWS CloudHSM", "Amazon EBS"], c: 0, e: "Elastic Beanstalk gère automatiquement le provisionnement, l’équilibrage de charge, la mise à l’échelle et la supervision." },
  { d: 3, q: "Quel service propose des serveurs privés virtuels simples à un prix mensuel fixe, adaptés aux petits projets ?", a: ["Amazon Lightsail", "Amazon EKS", "AWS Outposts", "Amazon EMR"], c: 0, e: "Lightsail regroupe serveur, stockage et transfert de données dans une offre simple et prévisible." },
  { d: 3, q: "Quel moteur de calcul serverless permet d’exécuter des conteneurs sans gérer d’instances EC2 ?", a: ["AWS Fargate", "Amazon ECR", "Amazon EC2 Auto Scaling", "AWS Lambda Layers"], c: 0, e: "Fargate fonctionne avec ECS et EKS et supprime la gestion des serveurs pour les conteneurs." },
  { d: 3, q: "Quel service exécute Kubernetes de manière managée sur AWS ?", a: ["Amazon EKS", "Amazon ECS", "AWS Batch", "Amazon MQ"], c: 0, e: "Amazon Elastic Kubernetes Service (EKS) gère le plan de contrôle Kubernetes." },
  { d: 3, q: "Où stocker et gérer des images de conteneurs Docker sur AWS ?", a: ["Amazon ECR", "Amazon EFS", "AWS Artifact", "Amazon S3 Glacier"], c: 0, e: "Amazon Elastic Container Registry (ECR) est un registre d’images de conteneurs managé." },
  { d: 3, q: "Quel service fournit des volumes de stockage bloc persistants pour les instances EC2 ?", a: ["Amazon EBS", "Amazon S3", "Amazon EFS", "AWS Storage Gateway"], c: 0, e: "Amazon EBS fournit des volumes bloc qui persistent indépendamment de la vie de l’instance, dans une Availability Zone." },
  { d: 3, q: "Qu’arrive-t-il aux données d’un stockage d’instance (instance store) quand l’instance EC2 est arrêtée ?", a: ["Elles sont conservées", "Elles sont perdues", "Elles sont copiées dans S3", "Elles sont archivées dans Glacier"], c: 1, e: "Le stockage d’instance est temporaire : il convient aux caches et données temporaires, pas aux données à conserver." },
  { d: 3, q: "Plusieurs instances Linux dans différentes AZ doivent partager un même système de fichiers. Quel service choisir ?", a: ["Amazon EFS", "Amazon EBS", "Stockage d’instance", "Amazon S3 Glacier"], c: 0, e: "Amazon EFS est un système de fichiers NFS élastique accessible simultanément par de nombreuses instances." },
  { d: 3, q: "Quel service fournit un système de fichiers Windows managé compatible SMB ?", a: ["Amazon FSx for Windows File Server", "Amazon EFS", "Amazon EBS", "AWS DataSync"], c: 0, e: "FSx for Windows File Server offre un stockage de fichiers entièrement managé et compatible avec Active Directory." },
  { d: 3, q: "Quelle classe de stockage S3 est la moins chère pour des archives consultées une ou deux fois par an ?", a: ["S3 Glacier Deep Archive", "S3 Standard", "S3 Standard-IA", "S3 Intelligent-Tiering"], c: 0, e: "Glacier Deep Archive est la classe la moins chère, avec une récupération en 12 heures ou plus." },
  { d: 3, q: "Quelle classe S3 est adaptée à des données dont les modèles d’accès sont inconnus ou changeants ?", a: ["S3 Intelligent-Tiering", "S3 One Zone-IA", "S3 Glacier Flexible Retrieval", "S3 Standard"], c: 0, e: "Intelligent-Tiering déplace automatiquement les objets entre niveaux d’accès pour optimiser les coûts." },
  { d: 3, q: "Des copies de données, rarement consultées et faciles à recréer, doivent être stockées au coût le plus bas avec un accès rapide. Quelle classe S3 choisir ?", a: ["S3 One Zone-IA", "S3 Standard", "S3 Glacier Deep Archive", "S3 Express One Zone"], c: 0, e: "One Zone-IA stocke les données dans une seule AZ à moindre coût : acceptable pour des données recréables." },
  { d: 3, q: "Quelle est la durabilité conçue d’Amazon S3 Standard ?", a: ["99,9 %", "99,99 %", "99,999999999 % (11 neuf)", "100 %"], c: 2, e: "S3 est conçu pour une durabilité de 11 neuf en répliquant les objets sur plusieurs AZ." },
  { d: 3, q: "Quelle fonctionnalité S3 déplace automatiquement les objets vers Glacier après 90 jours ?", a: ["Les politiques de cycle de vie", "Le versioning", "La réplication entre Régions", "S3 Transfer Acceleration"], c: 0, e: "Les règles de cycle de vie font transiter ou expirer automatiquement les objets selon leur âge." },
  { d: 3, q: "Quelle fonctionnalité S3 permet de récupérer un objet supprimé ou écrasé par erreur ?", a: ["Le versioning", "Les politiques de cycle de vie", "Le chiffrement SSE-S3", "Les URL présignées"], c: 0, e: "Le versioning conserve plusieurs versions d’un objet, ce qui protège contre les suppressions et écrasements accidentels." },
  { d: 3, q: "Quel service relie les applications sur site au stockage cloud AWS dans une architecture hybride ?", a: ["AWS Storage Gateway", "Amazon CloudFront", "AWS Lambda", "Amazon Kinesis"], c: 0, e: "Storage Gateway donne aux applications sur site un accès quasi illimité au stockage AWS (S3, FSx, EBS)." },
  { d: 3, q: "Quel service centralise et automatise les sauvegardes de plusieurs services AWS (EBS, RDS, DynamoDB, EFS…) ?", a: ["AWS Backup", "AWS Config", "Amazon S3 Glacier", "AWS CloudTrail"], c: 0, e: "AWS Backup applique des plans de sauvegarde centralisés sur de nombreux services." },
  { d: 3, q: "Quelle base de données NoSQL clé-valeur serverless offre une latence de quelques millisecondes à n’importe quelle échelle ?", a: ["Amazon DynamoDB", "Amazon RDS", "Amazon Redshift", "Amazon Aurora"], c: 0, e: "DynamoDB est entièrement managée et serverless, et met à l’échelle automatiquement." },
  { d: 3, q: "Quelle base de données relationnelle, compatible MySQL et PostgreSQL, a été conçue par AWS pour de hautes performances ?", a: ["Amazon Aurora", "Amazon DocumentDB", "Amazon Neptune", "Amazon Keyspaces"], c: 0, e: "Aurora offre des performances élevées et un stockage répliqué sur trois Availability Zones." },
  { d: 3, q: "Quel service est un entrepôt de données pour analyser des pétaoctets de données avec SQL ?", a: ["Amazon Redshift", "Amazon DynamoDB", "Amazon ElastiCache", "Amazon RDS for MySQL"], c: 0, e: "Redshift est un entrepôt de données en colonnes optimisé pour les requêtes analytiques." },
  { d: 3, q: "Quel service réduit la charge d’une base de données en mettant en cache les requêtes fréquentes en mémoire ?", a: ["Amazon ElastiCache", "Amazon S3", "AWS Backup", "Amazon Athena"], c: 0, e: "ElastiCache fournit des caches en mémoire (Redis, Valkey, Memcached) avec des temps de réponse inférieurs à la milliseconde." },
  { d: 3, q: "Un réseau social veut stocker et interroger des relations entre utilisateurs. Quelle base de données est la plus adaptée ?", a: ["Amazon Neptune", "Amazon Redshift", "Amazon RDS", "Amazon Timestream"], c: 0, e: "Neptune est une base de données orientée graphe, idéale pour des données très connectées." },
  { d: 3, q: "Quel service de base de données est compatible avec MongoDB ?", a: ["Amazon DocumentDB", "Amazon Aurora", "Amazon Neptune", "Amazon QLDB"], c: 0, e: "Amazon DocumentDB est une base de documents JSON managée compatible avec les API MongoDB." },
  { d: 3, q: "Quelle option d’Amazon RDS améliore la disponibilité grâce à une instance de secours dans une autre Availability Zone ?", a: ["Le déploiement Multi-AZ", "Les réplicas en lecture", "Les instantanés manuels", "Les instances réservées"], c: 0, e: "En Multi-AZ, RDS réplique les données de manière synchrone et bascule automatiquement en cas de panne." },
  { d: 3, q: "Une application RDS reçoit beaucoup de requêtes de lecture. Quelle fonctionnalité améliore les performances ?", a: ["Les réplicas en lecture", "Le déploiement Multi-AZ", "AWS Shield", "Amazon EBS Snapshots"], c: 0, e: "Les réplicas en lecture répartissent la charge de lecture sur des copies de la base." },
  { d: 3, q: "Quels services AWS sont considérés comme serverless ? (Choisissez 2 réponses)", a: ["AWS Lambda", "Amazon DynamoDB", "Amazon EC2", "Amazon EBS", "AWS Outposts"], c: [0, 1], e: "Lambda et DynamoDB ne nécessitent aucune gestion de serveurs. EC2 et Outposts impliquent de gérer des serveurs, EBS est attaché à des instances." },
  { d: 3, q: "Quel service permet de créer un réseau virtuel isolé logiquement dans le cloud AWS ?", a: ["Amazon VPC", "AWS Direct Connect", "Amazon Route 53", "Amazon CloudFront"], c: 0, e: "Un Amazon VPC permet de définir plages d’adresses IP, sous-réseaux, tables de routage et passerelles." },
  { d: 3, q: "Quel composant permet aux ressources d’un VPC de communiquer avec Internet ?", a: ["La passerelle Internet (Internet Gateway)", "Le groupe IAM", "Le point de terminaison S3", "La network ACL"], c: 0, e: "Une Internet Gateway attachée au VPC, avec une route adaptée, permet la communication avec Internet." },
  { d: 3, q: "Des instances dans un sous-réseau privé doivent télécharger des mises à jour sans être accessibles depuis Internet. Quelle solution utiliser ?", a: ["Une passerelle NAT", "Une adresse IP publique sur chaque instance", "AWS Direct Connect", "Amazon CloudFront"], c: 0, e: "La passerelle NAT permet les connexions sortantes vers Internet tout en bloquant les connexions entrantes initiées de l’extérieur." },
  { d: 3, q: "Qu’est-ce qui rend un sous-réseau « public » ?", a: ["Sa table de routage contient une route vers une passerelle Internet", "Il contient une instance EC2", "Il est chiffré avec KMS", "Il appartient au compte root"], c: 0, e: "Un sous-réseau est public si sa table de routage dirige le trafic Internet vers une Internet Gateway." },
  { d: 3, q: "Quel service fournit le DNS, l’enregistrement de noms de domaine et le routage basé sur la latence ?", a: ["Amazon Route 53", "Amazon CloudFront", "Elastic Load Balancing", "AWS Global Accelerator"], c: 0, e: "Route 53 est un service DNS hautement disponible avec plusieurs politiques de routage et des contrôles de santé." },
  { d: 3, q: "Quel service réduit la latence d’un site web en distribuant le contenu via un réseau mondial d’emplacements périphériques ?", a: ["Amazon CloudFront", "Amazon VPC", "AWS Direct Connect", "Amazon EFS"], c: 0, e: "CloudFront est le CDN d’AWS : il met en cache le contenu au plus près des utilisateurs." },
  { d: 3, q: "Une entreprise a besoin d’une connexion réseau privée, dédiée et à bande passante constante entre son datacenter et AWS. Quel service choisir ?", a: ["AWS Direct Connect", "AWS Site-to-Site VPN", "Amazon CloudFront", "Internet Gateway"], c: 0, e: "Direct Connect établit une liaison physique dédiée qui ne passe pas par l’Internet public." },
  { d: 3, q: "Quelle solution établit rapidement une connexion chiffrée entre un réseau sur site et un VPC via Internet ?", a: ["AWS Site-to-Site VPN", "AWS Direct Connect", "VPC Peering", "Amazon Route 53"], c: 0, e: "Un Site-to-Site VPN crée des tunnels IPsec chiffrés via Internet ; il se met en place bien plus vite que Direct Connect." },
  { d: 3, q: "Quel service utilise le réseau mondial AWS et des adresses IP statiques pour améliorer la disponibilité et les performances d’applications mondiales ?", a: ["AWS Global Accelerator", "Amazon CloudFront", "AWS Transit Gateway", "Amazon API Gateway"], c: 0, e: "Global Accelerator dirige le trafic vers le point de terminaison sain le plus proche via le réseau AWS." },
  { d: 3, q: "Quel service permet de décrire et de provisionner l’infrastructure AWS à l’aide de modèles (infrastructure as code) ?", a: ["AWS CloudFormation", "Amazon CloudWatch", "AWS Config", "AWS Trusted Advisor"], c: 0, e: "CloudFormation crée des piles de ressources de manière reproductible à partir de modèles JSON ou YAML." },
  { d: 3, q: "Quel service collecte des métriques et des journaux et déclenche des alarmes, par exemple si l’utilisation CPU dépasse 80 % ?", a: ["Amazon CloudWatch", "AWS CloudTrail", "AWS X-Ray", "AWS Artifact"], c: 0, e: "CloudWatch surveille les ressources et les applications, et déclenche des alarmes et des actions." },
  { d: 3, q: "Quel service envoie des notifications à des abonnés par e-mail, SMS ou vers d’autres services (publication/abonnement) ?", a: ["Amazon SNS", "Amazon SQS", "Amazon SES", "AWS Step Functions"], c: 0, e: "Amazon Simple Notification Service diffuse des messages à de multiples abonnés." },
  { d: 3, q: "Quel service met des messages en file d’attente pour découpler les composants d’une application ?", a: ["Amazon SQS", "Amazon SNS", "Amazon Kinesis Video Streams", "AWS Glue"], c: 0, e: "Amazon Simple Queue Service stocke les messages jusqu’à ce qu’un consommateur les traite." },
  { d: 3, q: "Quel service permet d’exécuter des requêtes SQL directement sur des données stockées dans Amazon S3, sans serveur ?", a: ["Amazon Athena", "Amazon Redshift", "Amazon RDS", "Amazon DynamoDB"], c: 0, e: "Athena est un service de requêtes interactif et serverless, facturé à la quantité de données analysées." },
  { d: 3, q: "Quel service collecte et traite des flux de données en temps réel, comme des clics ou des données d’objets connectés ?", a: ["Amazon Kinesis", "AWS Batch", "Amazon S3 Glacier", "AWS Snowball"], c: 0, e: "Kinesis permet d’ingérer et d’analyser des données en streaming en temps réel." },
  { d: 3, q: "Quel service crée des tableaux de bord de business intelligence interactifs ?", a: ["Amazon QuickSight", "Amazon CloudWatch Logs", "AWS Glue", "Amazon Macie"], c: 0, e: "QuickSight est un service de BI serverless pour créer visualisations et tableaux de bord." },
  { d: 3, q: "Quel service permet de créer, entraîner et déployer des modèles de machine learning personnalisés ?", a: ["Amazon SageMaker AI", "Amazon Rekognition", "Amazon Polly", "Amazon Lex"], c: 0, e: "SageMaker AI fournit les outils pour tout le cycle de vie du machine learning." },
  { d: 3, q: "Quel service analyse des images et des vidéos pour détecter des objets, des visages ou du texte ?", a: ["Amazon Rekognition", "Amazon Comprehend", "Amazon Transcribe", "Amazon Textract"], c: 0, e: "Rekognition est un service d’analyse d’images et de vidéos basé sur le deep learning." },
  { d: 3, q: "Quel service donne accès, via une API, à des modèles de fondation pour créer des applications d’IA générative ?", a: ["Amazon Bedrock", "Amazon Kendra", "AWS Glue", "Amazon Personalize"], c: 0, e: "Bedrock propose des modèles de fondation de plusieurs fournisseurs, sans gérer d’infrastructure." },
  { d: 3, q: "Quel service convertit automatiquement la parole en texte ?", a: ["Amazon Transcribe", "Amazon Polly", "Amazon Translate", "Amazon Lex"], c: 0, e: "Transcribe fait de la reconnaissance vocale ; Polly fait l’inverse (texte vers parole)." },
  { d: 3, q: "Quel service convertit du texte en parole réaliste ?", a: ["Amazon Polly", "Amazon Transcribe", "Amazon Comprehend", "Amazon Rekognition"], c: 0, e: "Amazon Polly synthétise la parole à partir de texte dans de nombreuses langues et voix." },
  { d: 3, q: "Quel service analyse du texte pour en extraire le sentiment, les entités et les phrases clés ?", a: ["Amazon Comprehend", "Amazon Textract", "Amazon Translate", "Amazon Lex"], c: 0, e: "Comprehend est un service de traitement du langage naturel (NLP)." },
  { d: 3, q: "Quel service permet de gérer un parc d’instances, d’appliquer des correctifs et de s’y connecter sans ouvrir le port SSH ?", a: ["AWS Systems Manager", "AWS CloudFormation", "Amazon Inspector", "AWS Config"], c: 0, e: "Systems Manager inclut Patch Manager, Run Command et Session Manager pour l’accès sans SSH." },
  { d: 3, q: "Quelles méthodes permettent d’interagir avec les services AWS ? (Choisissez 2 réponses)", a: ["La console de gestion AWS", "L’interface en ligne de commande AWS CLI", "AWS Artifact", "Amazon Route 53", "AWS Snowcone"], c: [0, 1], e: "On accède à AWS via la console web, la CLI, les SDK et les API. Les autres réponses sont des services." },
  { d: 3, q: "Quel service aide à tracer les requêtes à travers une application distribuée pour identifier les goulots d’étranglement ?", a: ["AWS X-Ray", "AWS CloudTrail", "Amazon GuardDuty", "AWS Trusted Advisor"], c: 0, e: "X-Ray fournit une vue de bout en bout des requêtes à travers les services d’une application." },
  { d: 3, q: "Quel service déclenche une fonction Lambda chaque nuit à 2 heures ou en réaction à un événement AWS ?", a: ["Amazon EventBridge", "Amazon SQS", "AWS Batch", "Amazon Route 53"], c: 0, e: "EventBridge est un bus d’événements serverless qui gère aussi les planifications." },
  { d: 3, q: "Quel service fournit des bureaux virtuels Windows ou Linux aux employés ?", a: ["Amazon WorkSpaces", "Amazon Lightsail", "AWS Outposts", "Amazon AppFlow"], c: 0, e: "Amazon WorkSpaces est une solution de bureaux virtuels (DaaS) managée." },
  { d: 3, q: "Quel service serverless prépare et transforme des données (ETL) pour l’analytique ?", a: ["AWS Glue", "Amazon ElastiCache", "AWS Direct Connect", "Amazon Lightsail"], c: 0, e: "AWS Glue découvre, catalogue et transforme les données pour les rendre exploitables." },

  // ── Domaine 4 : Facturation, tarification et support ──────────────────────
  { d: 4, q: "Quel outil analyse les coûts AWS au fil du temps et propose des prévisions ?", a: ["AWS Cost Explorer", "Amazon Inspector", "AWS Artifact", "AWS Shield"], c: 0, e: "Cost Explorer permet d’explorer les coûts, de filtrer les dépenses, d’identifier les tendances et de prévoir les coûts futurs." },
  { d: 4, q: "Quel service fournit des recommandations pour optimiser les coûts, la sécurité, les performances et la tolérance aux pannes ?", a: ["AWS Trusted Advisor", "Amazon Macie", "AWS WAF", "Amazon Route 53"], c: 0, e: "Trusted Advisor analyse votre environnement et formule des recommandations selon les bonnes pratiques AWS." },
  { d: 4, q: "Une application de test tourne quelques heures de manière imprévisible et ne doit pas être interrompue. Quel modèle de tarification EC2 choisir ?", a: ["On-Demand", "Spot Instances", "Reserved Instances 3 ans", "Dedicated Hosts"], c: 0, e: "On-Demand ne demande aucun engagement et convient aux charges courtes, imprévisibles et non interruptibles." },
  { d: 4, q: "Une base de données tourne 24/7 depuis des années avec une charge stable. Quelle option réduit le plus son coût ?", a: ["Reserved Instances ou Savings Plans sur 3 ans", "On-Demand", "Spot Instances", "Arrêter l’instance la nuit"], c: 0, e: "Les engagements sur 1 ou 3 ans offrent jusqu’à 72 % de réduction pour les charges stables et prévisibles." },
  { d: 4, q: "Des traitements par lots flexibles peuvent être interrompus et relancés. Quel modèle EC2 est le plus économique ?", a: ["Spot Instances", "On-Demand", "Dedicated Instances", "Reserved Instances"], c: 0, e: "Les instances Spot offrent jusqu’à 90 % de réduction mais peuvent être récupérées par AWS avec un préavis de 2 minutes." },
  { d: 4, q: "Quel modèle de tarification offre des réductions en échange d’un engagement sur un montant horaire, applicable à EC2, Fargate et Lambda ?", a: ["Savings Plans", "Reserved Instances standard", "Spot Instances", "AWS Free Tier"], c: 0, e: "Les Compute Savings Plans s’appliquent quelle que soit la famille d’instance, la Région ou le service de calcul." },
  { d: 4, q: "Une entreprise doit utiliser ses licences logicielles liées aux cœurs physiques d’un serveur. Quelle option EC2 choisir ?", a: ["Dedicated Hosts", "Spot Instances", "On-Demand partagé", "AWS Lambda"], c: 0, e: "Les Dedicated Hosts donnent une visibilité sur les sockets et cœurs physiques, utile pour les licences BYOL." },
  { d: 4, q: "Quelle option de paiement des Reserved Instances offre la réduction la plus importante ?", a: ["Tout payé d’avance (All Upfront)", "Paiement partiel d’avance", "Aucun paiement initial", "Paiement à la seconde"], c: 0, e: "Plus le paiement initial est élevé, plus la réduction est importante." },
  { d: 4, q: "Quel service envoie une alerte quand les dépenses mensuelles dépassent un seuil défini ?", a: ["AWS Budgets", "AWS Cost Explorer", "AWS Pricing Calculator", "Amazon CloudFront"], c: 0, e: "AWS Budgets suit les coûts et l’utilisation et envoie des alertes en cas de dépassement réel ou prévu." },
  { d: 4, q: "Quel outil permet d’estimer le coût mensuel d’une architecture avant de la déployer ?", a: ["AWS Pricing Calculator", "AWS Cost Explorer", "AWS Budgets", "AWS Cost and Usage Report"], c: 0, e: "Le Pricing Calculator estime les coûts de services AWS à partir d’une configuration prévue." },
  { d: 4, q: "Quel rapport fournit le niveau de détail le plus fin sur les coûts et l’utilisation AWS ?", a: ["AWS Cost and Usage Report (CUR)", "La facture mensuelle PDF", "AWS Health Dashboard", "AWS Trusted Advisor"], c: 0, e: "Le CUR contient des lignes détaillées par heure, ressource et balise, exploitables avec Athena ou QuickSight." },
  { d: 4, q: "Quel est un avantage de la facturation consolidée d’AWS Organizations ?", a: ["Une facture unique et des remises sur volume partagées entre comptes", "La gratuité de tous les services", "Un TAM dédié", "La suppression des coûts de transfert"], c: 0, e: "La facturation consolidée agrège l’utilisation de tous les comptes, ce qui permet d’atteindre plus vite les paliers de prix." },
  { d: 4, q: "Comment répartir les coûts AWS entre différents projets ou départements ?", a: ["Utiliser des balises de répartition des coûts", "Créer un utilisateur root par projet", "Utiliser des security groups", "Activer AWS Shield Advanced"], c: 0, e: "Les balises de répartition des coûts permettent de ventiler la facture dans Cost Explorer et le CUR." },
  { d: 4, q: "Quel type de transfert de données est généralement gratuit sur AWS ?", a: ["Le transfert entrant depuis Internet vers AWS", "Le transfert sortant vers Internet", "Le transfert entre Régions", "Le transfert vers un datacenter sur site"], c: 0, e: "Les données entrantes sont généralement gratuites ; les données sortantes vers Internet sont facturées." },
  { d: 4, q: "Comment AWS Lambda est-il facturé ?", a: ["Au nombre de requêtes et à la durée d’exécution", "Par serveur provisionné par mois", "Par nombre d’utilisateurs IAM", "Par licence annuelle"], c: 0, e: "Lambda facture le nombre d’invocations et la durée de calcul selon la mémoire allouée." },
  { d: 4, q: "Quels facteurs influencent le coût d’une instance EC2 ? (Choisissez 2 réponses)", a: ["Le type et la taille de l’instance", "La Région AWS", "Le nombre de groupes IAM", "Le nombre de balises", "Le nombre de politiques SCP"], c: [0, 1], e: "Le coût EC2 dépend notamment du type d’instance, de la Région, du modèle d’achat, du système d’exploitation et du temps d’exécution." },
  { d: 4, q: "Quel est le plan de support AWS le moins cher qui donne un accès 24/7 aux ingénieurs support par téléphone et chat ?", a: ["Business", "Developer", "Basic", "Enterprise"], c: 0, e: "Le plan Business est le premier à offrir un accès 24/7 par téléphone, chat et e-mail." },
  { d: 4, q: "Quel plan de support inclut un Technical Account Manager (TAM) désigné ?", a: ["Enterprise", "Enterprise On-Ramp", "Business", "Developer"], c: 0, e: "Le plan Enterprise inclut un TAM désigné ; Enterprise On-Ramp donne accès à un pool de TAM." },
  { d: 4, q: "Quel plan de support donne accès à un pool de Technical Account Managers et garantit une réponse en moins de 30 minutes pour un système critique ?", a: ["Enterprise On-Ramp", "Enterprise", "Business", "Developer"], c: 0, e: "Enterprise On-Ramp se situe entre Business et Enterprise, avec un pool de TAM." },
  { d: 4, q: "Qu’inclut le plan de support Basic, gratuit pour tous les clients ?", a: ["Un TAM désigné", "L’accès à AWS re:Post, à la documentation et aux contrôles essentiels de Trusted Advisor", "Le support téléphonique 24/7", "L’équipe Concierge"], c: 1, e: "Basic comprend la documentation, les livres blancs, AWS re:Post, AWS Health Dashboard et les contrôles essentiels de Trusted Advisor." },
  { d: 4, q: "Une équipe en phase d’expérimentation veut un support technique par e-mail aux heures ouvrées au moindre coût. Quel plan choisir ?", a: ["Developer", "Business", "Enterprise On-Ramp", "Enterprise"], c: 0, e: "Le plan Developer est adapté aux tests et au développement avec un support par e-mail aux heures ouvrées." },
  { d: 4, q: "À partir de quel plan de support l’ensemble des contrôles AWS Trusted Advisor est-il disponible ?", a: ["Business", "Basic", "Developer", "Tous les plans"], c: 0, e: "Basic et Developer ont accès aux contrôles essentiels ; Business, Enterprise On-Ramp et Enterprise ont tous les contrôles." },
  { d: 4, q: "Quel service informe des événements et maintenances AWS qui affectent spécifiquement vos ressources ?", a: ["AWS Health Dashboard", "AWS Cost Explorer", "AWS Artifact", "Amazon Inspector"], c: 0, e: "AWS Health Dashboard affiche l’état des services et les événements personnalisés pour votre compte." },
  { d: 4, q: "Où trouver et acheter des logiciels tiers prêts à déployer sur AWS ?", a: ["AWS Marketplace", "AWS Artifact", "AWS re:Post", "AWS Organizations"], c: 0, e: "AWS Marketplace est un catalogue numérique de logiciels, données et services de fournisseurs tiers." },
  { d: 4, q: "Quelle ressource communautaire permet de poser des questions techniques sur AWS et d’obtenir des réponses d’experts ?", a: ["AWS re:Post", "AWS Artifact", "AWS Budgets", "AWS Marketplace"], c: 0, e: "AWS re:Post est le service de questions-réponses communautaire d’AWS." },
  { d: 4, q: "Une entreprise cherche un cabinet de conseil certifié pour l’accompagner dans sa migration. Quelle ressource utiliser ?", a: ["AWS Partner Network (APN)", "AWS Trusted Advisor", "AWS Shield Advanced", "Amazon Connect"], c: 0, e: "L’AWS Partner Network regroupe des partenaires conseil et technologie validés par AWS." },
  { d: 4, q: "Quel service détecte automatiquement des dépenses inhabituelles grâce au machine learning ?", a: ["AWS Cost Anomaly Detection", "AWS Budgets Reports", "AWS Pricing Calculator", "Amazon GuardDuty"], c: 0, e: "Cost Anomaly Detection surveille les dépenses et alerte en cas de hausse anormale." },
  { d: 4, q: "Quel service recommande des tailles et types d’instances EC2 plus adaptés à partir de l’historique d’utilisation ?", a: ["AWS Compute Optimizer", "AWS Config", "Amazon EC2 Auto Scaling", "AWS Artifact"], c: 0, e: "Compute Optimizer utilise le machine learning pour recommander un dimensionnement optimal." },
  { d: 4, q: "Quels éléments sont facturés pour Amazon S3 ? (Choisissez 2 réponses)", a: ["Le volume de données stockées", "Les requêtes et le transfert de données sortant", "Le transfert entrant depuis Internet", "La création du bucket", "Le nombre d’utilisateurs IAM"], c: [0, 1], e: "S3 facture le stockage (selon la classe), les requêtes et le transfert sortant. L’entrée des données est gratuite." }
];
